    if (text !== null) {
      const manifest = rel === "Cargo.toml" ? "" : ` --manifest-path ${rel}`;
      const target = path.join(os.tmpdir(), `nexus-typecheck-${sha(root).slice(0, 16)}`);
      return {
        tool: "cargo",
        probe: "cargo --version",
        command: `CARGO_TARGET_DIR='${target}' cargo check --offline --locked${manifest}`,
        configPath: rel,
        configSha256: sha(text),
        toolSha256: sha256File(resolveOnPath("cargo") ?? ""),
        ...(resolveOnPath("cargo") ? {} : { missingTool: true }),
      };
    }
  }
  const gomod = read("go.mod");
  if (gomod !== null) {
    const go = resolveOnPath("go");
    return {
      tool: "go",
      probe: "go version",
      // Offline: a module that is not already downloaded is an environment problem, never a fetch.
      command: "GOPROXY=off GOFLAGS=-mod=mod go vet ./...",
      configPath: "go.mod",
      configSha256: sha(gomod),
      toolSha256: sha256File(go ?? ""),
      ...(go ? {} : { missingTool: true }),
    };
  }
  return discoverPythonTypecheck(root, read, sha);
}

/** Python is checked only when the project configures pyright or mypy; the tool comes from the project's virtualenv or PATH. */
function discoverPythonTypecheck(root: string, read: (rel: string) => string | null, sha: (text: string) => string): DiscoveredTypecheck | null {
  const pyproject = read("pyproject.toml") ?? "";
  const setupCfg = read("setup.cfg") ?? "";
  const candidates: Array<{ tool: "pyright" | "mypy"; configPath: string; text: string }> = [];
  const pyrightJson = read("pyrightconfig.json");
  if (pyrightJson !== null) candidates.push({ tool: "pyright", configPath: "pyrightconfig.json", text: pyrightJson });
  if (/^\[tool\.pyright\]/m.test(pyproject)) candidates.push({ tool: "pyright", configPath: "pyproject.toml", text: pyproject });
  for (const rel of ["mypy.ini", ".mypy.ini"]) {
    const text = read(rel);
    if (text !== null) candidates.push({ tool: "mypy", configPath: rel, text });
  }
  if (/^\[tool\.mypy\]/m.test(pyproject)) candidates.push({ tool: "mypy", configPath: "pyproject.toml", text: pyproject });
  if (/^\[mypy\]/m.test(setupCfg)) candidates.push({ tool: "mypy", configPath: "setup.cfg", text: setupCfg });
  const chosen = candidates[0];
  if (!chosen) return null;
  const local = [".venv/bin", "venv/bin"].map((d) => path.join(root, d, chosen.tool)).find((f) => fs.existsSync(f));
  const resolved = local ?? resolveOnPath(chosen.tool);
  const launcher = local ? `./${path.relative(root, local)}` : chosen.tool;
  return {
    tool: chosen.tool,
    probe: `${launcher} --version`,
    command: chosen.tool === "mypy" ? `${launcher} .` : launcher,
    configPath: chosen.configPath,
    configSha256: sha(chosen.text),
    toolSha256: sha256File(resolved ?? ""),
    ...(resolved ? {} : { missingTool: true }),
  };
}

export interface TypecheckDiagnostics {
  errorCount: number;
  /** Files (as printed by the tool) that carry at least one located error. */
  files: string[];
  /** Error codes of diagnostics with no source location (configuration errors). */
  unlocatedCodes: string[];
  first: string[];
  /** Every located error as file (as printed) and the message without its line and column. */
  located: Array<{ file: string; text: string }>;
}

/** tsc `path(line,col): error TSxxxx` and `path:line:col - error TSxxxx`; cargo `error...` followed by `--> path:line:col`. */
export function parseTypecheckDiagnostics(output: string): TypecheckDiagnostics {
  const files = new Set<string>();
  const unlocatedCodes: string[] = [];
  const first: string[] = [];
  const located: Array<{ file: string; text: string }> = [];
  let errorCount = 0;
  let cargoError: string | undefined;
  const note = (line: string, file?: string, text?: string) => {
    errorCount++;
    if (file !== undefined) located.push({ file, text: (text ?? line).trim().slice(0, 240) });
    if (first.length < 5) first.push(line.trim().slice(0, 240));
  };
  for (const raw of output.split("\n")) {
    const line = raw.replace(/\r$/, "");
    const tsc = line.match(/^(.+?)\((\d+),(\d+)\): error (TS\d+):/) ?? line.match(/^(.+?):(\d+):(\d+) - error (TS\d+):/);
    if (tsc) {
      files.add(tsc[1]);
      note(line, tsc[1], line.slice(line.indexOf(" error ") + 1));
      continue;
    }
            const isTrusted = isWorkspaceTrusted(this.config.workspace, this.isReadOnly());
            const mode = this.getApprovalMode();
            const policyContext: PolicyContext = {
              mode,
              trusted: isTrusted,
              sandbox: this.config.sandbox,
              approvedEgressOrigins: this.approvedEgressOrigins,
              fullAccess: Boolean(this.config.fullAccess) && !this.isReadOnly(),
            };
            const error = (!onConfirm && this.approvalPolicy.requiresDecision("exec", policyContext))
              ? `Error: Verifier '${verifierCommand}' requires operator approval (exec), but no operator is present (headless execution). Run with --yes or --mode auto to explicitly select automatic approvals.`
              : `Verification Oracle: verifier execution was not approved by operator (${verifierCommand}).`;
            return {
              success: false,
              output: "",
              error,
            };
          }

          // The oracle owns the verifier's deadline (never an incidental bridge default); the runner enforces it.
          const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
          this.activity("verifying", { tool: verifierCommand });
          verificationStateBefore = this.isRecordableWorktree() && !this.config.dryRun ? captureVerificationState(this.config.workspace) : undefined;
          const verifierStartedAt = Date.now();
          const testRes = await runTestSuiteWithExecutor(
            this.config.workspace,
            (command) => this.bridge.executeTool("run_command", { command, timeout_secs: deadlineSecs }),
            verifierCommand
          );
          // Configured or discovered, a verifier is evidence about the change only when its run shows tests that
          // executed and cover the changed files.
          hasExecuted = hasExecutedTests(testRes.rawOutput || "");
          const baselineTests = this.changeBaseline?.tests;
          const baselineTestsChanged = !baselineTests || testsChangedSince(this.config.workspace, baselineTests);
          // A generic current-invocation verifier cannot authenticate recovered scope or its
          // candidate-controlled tests. Only a verifier definition and test snapshot captured
          // before the current task's edits can bind workspace changes.
          const configuredTestsStable = source !== "configured" || !baselineTestsChanged;
          isDeliverableBound = (!this.verificationBaselineInvalidated && hasExecuted && configuredTestsStable && isVerifierDeliverableBound(
            this.config.workspace,
            Array.from(this.modifiedFiles),
            verifierCommand,
            testRes.rawOutput || "",
            this.changeBaseline?.trustedDeliverables?.length
              ? trustedDeliverablesFromBaseline(this.changeBaseline)
              : new Set(this.config.trustedDeliverableFiles ?? []),
            baselineTests ?? undefined,
          ));
          // A passing verifier is not acceptance while the project's type-check fails under its own configuration.
          const typecheckOutcome = testRes.success
            ? await this.runTypecheckOracle({
                candidateId,
                current,
                budgetSecs: Math.max(30, deadlineSecs - Math.round((Date.now() - verifierStartedAt) / 1000)),
                onConfirm,
                configured: Boolean(configured),
              })
            : undefined;
          const typecheck = typecheckOutcome?.evidence;
          const typecheckBlock = typecheckOutcome?.block;
          const testsAndTypesPass = testRes.success && !typecheckBlock;
          // A discovered verifier's pass makes the change VERIFIED only on independent evidence (fail-before /
          // pass-after on tests the change did not write); the operator's configured verifier is their own check.
          const independence: Independence | undefined = unboundDetail
            ? { independent: false, detail: unboundDetail }
            : source === "discovered" && testsAndTypesPass && isDeliverableBound ? await this.judgeIndependence(verifierCommand, deadlineSecs, onConfirm) : undefined;
          const evidence: VerificationEvidence = {
            status: testsAndTypesPass ? "PASSED" : testRes.timedOut ? "TIMED_OUT" : "FAILED",
            command: verifierCommand,
            source,
            exitSuccess: testsAndTypesPass,
            hasExecutedTests: hasExecuted,
            ...(typecheck ? { typecheck } : {}),
            isDeliverableBound,
            ...(unboundDetail ? { definitionBound: false } : {}),
            ...(independence ? { independent: independence.independent, independenceDetail: independence.detail } : {}),
            ...(testRes.timedOut ? { deadlineSecs } : {}),
            outputSha256: createHash("sha256").update(testRes.rawOutput || "").digest("hex"),
            candidateId,
            at: new Date().toISOString(),
          };
          this.verificationEvidence = evidence;
          this.verificationEvidenceRawOutput = testRes.rawOutput || "";
          this.turnVerifierRuns.push({ command: verifierCommand, phase: "completion", passed: testsAndTypesPass });
          if (configured) this.turnConfiguredVerifier = testsAndTypesPass ? "PASSED" : "FAILED";
          if (this.objective && candidateId) {
            recordAttempt(this.objective, {
              command: verifierCommand,
              inputs: candidateId,
              epoch: this.epoch,
              // Read after the run: the verifier's own command is not a change to its inputs.
  to: RequirementStatus;
  reason: string;
}

export interface SteeringRecord {
  id: string;
  text: string;
  receivedAt: string;
  status: "queued" | "applied" | "cancelled";
  appliedAt?: string;
  appliedAtStep?: number;
}

/** Steering that negates a requirement: held out of the conversation and the ledger until the operator decides. */
export interface SteeringConflict {
  id: string;
  text: string;
  requirements: string[];
  receivedAt: string;
  /** `unresolved`: no operator was available, so the ledger is unchanged and the negation was not applied. */
  status: "pending" | "approved" | "declined" | "unresolved";
  decidedAt?: string;
}

/** Requirements of an earlier objective still unmet when a new request replaced it; the operator decides what happens to them. */
export interface SupersededObjective {
  at: string;
  objective: string;
  objectiveSha256: string;
  requirements: Array<{ id: string; text: string; status: RequirementStatus }>;
  status: "pending_decision";
}

export interface VerificationAttempt {
  n: number;
  command: string;
  /** Candidate identity of the workspace the verifier ran on (tracked and untracked, non-ignored files). */
  inputs: string;
  /**
   * What else must be unchanged before a prior failure is reused: the agent process that ran it, the count of
   * mutating tool calls (any edit, write or shell command) at that time, and a fingerprint of inputs git ignores
   * (PATH, dependency install markers, .env files).
   */
  epoch?: string;
  mutationSeq?: number;
  external?: string;
  status: VerificationStatus | "SKIPPED_UNCHANGED_INPUTS";
  isDeliverableBound?: boolean;
  /** False when the run passed but nothing independent of the agent shows the change (see core/independent_check). */
  independent?: boolean;
  filtered?: boolean;
  /** Set when the run was a constraint's own verifier: it is evidence for that requirement only, never a general test run. */
  requirementId?: string;
  at: string;
  /** First failing line of the verifier's output, when it failed. */
  failedCheck?: string;
  /** ENVIRONMENT: the verifier could not run (tool missing, exit 126/127, sandbox error); it says nothing about the candidate. */
  classification?: "ENVIRONMENT" | "CANDIDATE_FAILED";
  /** The verifier process's exit code; absent when it never ran or was killed. */
  exitCode?: number;
  /** Names of the failing tests (redacted, capped). */
  failingTests?: string[];
  /** How many distinct failing tests the run named, uncapped (up to MAX_COUNTED_FAILING_TESTS); absent on older attempts. */
  failingTotal?: number;
  /** True when `failingTests` holds fewer names than the run reported. */
  failingTruncated?: boolean;
