      ...(run.errorCount !== undefined ? { errorCount: run.errorCount, firstDiagnostics: (run.firstDiagnostics ?? []).map((d) => safeTerminal(d)) } : {}),
      ...(baseline ? { baselineErrorCount: baseline.size } : {}),
      ...(run.introducedCount !== undefined ? { introducedCount: run.introducedCount } : {}),
      ...(shellChanged.length ? { shellChangedFiles: shellChanged.slice(0, 20) } : {}),
      scope: `under ${check.configPath}`,
      ...(run.status === "PASSED" ? {} : { excerpt }), candidateId: opts.candidateId, at: at(),
    };
    results.push(evidence);
    const blocking = run.status === "FAILED" || run.status === "TIMED_OUT";
    if (ledger && current && (blocking || run.status === "PASSED")) recordAttempt(ledger, {
      command: check.command, ...current, mutationSeq: this.mutationSeq,
      status: run.status === "PASSED" ? "PASSED" : run.status === "TIMED_OUT" ? "TIMED_OUT" : "FAILED",
      ...(blocking ? {
        failedCheck: safeTerminal(run.firstDiagnostics?.[0] ?? run.status).slice(0, 240),
        ...attemptEvidence(run.output, run.exitCode, { timedOut: run.status === "TIMED_OUT" }),
        ...(run.status === "FAILED" ? { classification: "CANDIDATE_FAILED" as const, failingTests: (run.firstDiagnostics ?? []).map((d) => safeTerminal(d).slice(0, 240)) } : {}),
      } : {}),
    });
    if (enforced && blocking) {
      const what = run.status === "FAILED" ? "failed" : `timed out after ${opts.budgetSecs}s`;
      blockingMessages.push(`${check.tool} type-check ${what} under ${check.configPath} (sha256 ${check.configSha256.slice(0, 12)}). Command: ${check.command}\n${excerpt}`);
    }
  }
  const primary = results.find((item) => item.status === "FAILED" || item.status === "TIMED_OUT") ?? results[0];
  const evidence: TypecheckEvidence = { ...primary, scope: results.length === 1 ? primary.scope : `${results.length} project check(s)`, projects: results };
  this.lastTypecheck = evidence;
  return { evidence, ...(blockingMessages.length ? { block: `Verification Oracle: tests passed, but a mandatory project type-check did not complete successfully; changes are NOT verified.\n${blockingMessages.join("\n\n") }\nFix the type errors or resolve the unavailable approval, then call task_completed again.` } : {}) };
}

export async function captureChangeBaselineImpl(this: any, confirmHandler?: ConfirmHandler): Promise<void> {
  // What was already changed when the task began (carried changes included), so only later shell changes are the candidate's.
  if (!this.preTaskChanged) {
    try {
      this.preTaskChanged = new Set(workspaceChangedPaths(this.config.workspace));
    } catch {}
  }
  // A new conversation does not make candidate writes from an interrupted or
  // resumed task trustworthy. Do not establish a discovered-verifier baseline
  // from a workspace that still carries an unverified-change obligation.
  if (this.hasPendingModifications || this.verificationBaselineInvalidated || this.changeBaseline !== undefined || this.config.dryRun || this.isReadOnly()) return;
  const configured = this.config.authoritativeVerifierCommand?.trim();
  const command = configured || discoverVerifier(this.config.workspace)?.command;
  if (!command) {
    this.changeBaseline = null;
    return;
  }
  this.judgeReceiptBaselineOnce(); // see the field: verification proceeds, no receipt is issued
  try {
    const tests = snapshotTests(this.config.workspace);
    const trustedDeliverables = [...(this.config.trustedDeliverableFiles ?? [])];
    const definition = this.verifierDefinitionAtCapture(command, trustedDeliverables);
    if (configured) {
      this.changeBaseline = { command, failed: false, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
      if (this.durable) {
        try {
          this.checkpointDurableState("configured verifier baseline captured");
        } catch (err: any) {
          this.reportPersistenceFailure("baseline", err);
        }
      }
      return;
    }
    const approved = await this.ensureVerifierApproved(command, confirmHandler, undefined, undefined, false);
    if (!approved) {
      this.changeBaseline = null;
      return;
    }
    this.activity("verifying", { tool: `${command} (before the change)` });
    const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
    const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: c, timeout_secs: deadlineSecs }), command);
    this.changeBaseline = { command, failed: !run.success, tests, ...definition, trustedDeliverables, at: new Date().toISOString() };
    this.turnVerifierRuns.push({ command, phase: "before_change", passed: run.success });
    await captureTypecheckBaselineImpl.call(this, confirmHandler, deadlineSecs);
    if (this.durable) {
      try {
        this.checkpointDurableState("baseline captured");
      } catch (err: any) {
        this.reportPersistenceFailure("baseline", err);
      }
    }
  } catch {
    this.changeBaseline = null;
}

const shellQuote = (value: string) => `'${value.replaceAll("'", "'\\''")}'`;
const shellPath = (value: string) => /^[A-Za-z0-9_./-]+$/.test(value) ? value : shellQuote(value);

/** Discover one check per configured project, including nested packages in a monorepo. */
export function discoverTypechecks(workspace: string): DiscoveredTypecheck[] {
  const root = path.resolve(workspace);
  const result: DiscoveredTypecheck[] = [];
  const ignored = new Set([".git", "node_modules", "target", "dist", "build", "coverage", ".venv", "venv", "vendor"]);
  const queue = [root];
  const seen = new Set<string>();
  // Bound repository-controlled traversal. If this limit is reached, callers get all checks found so far;
  // the explicit cap prevents a generated or hostile workspace from turning verification into an unbounded scan.
  const maxDirectories = 20_000;
  const maxChecks = 32;
  let capped = false;
  while (queue.length && seen.size < maxDirectories) {
    const project = queue.shift()!;
    let real: string;
    try { real = fs.realpathSync(project); } catch { continue; }
    if (seen.has(real) || (real !== root && !real.startsWith(`${root}${path.sep}`))) continue;
    seen.add(real);
    const check = discoverTypecheckAtRoot(root, project);
    if (check) {
      if (result.length >= maxChecks) { capped = true; break; }
      result.push(check);
    }
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(project, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      if (!entry.isDirectory() || ignored.has(entry.name)) continue;
      queue.push(path.join(project, entry.name));
    }
  }
  if (queue.length) capped = true;
  if (capped) result.push({ tool: "tsc", probe: "", command: "<bounded project discovery>", configPath: "<workspace project scan>", configSha256: "", skipReason: "workspace contains more projects than the bounded type-check discovery limit permits", discoveryIncomplete: true });
  return result;
}

/** Compatibility helper for callers that need the workspace-root project's check. */
export function discoverTypecheck(workspace: string): DiscoveredTypecheck | null {
  const root = path.resolve(workspace);
  return discoverTypecheckAtRoot(root, root) ?? discoverTypecheckAtRoot(root, path.join(root, "core"));
}

function discoverTypecheckAtRoot(root: string, project: string): DiscoveredTypecheck | null {
  const projectRelative = path.relative(root, project).split(path.sep).join("/");
  const prefix = projectRelative ? `cd ${shellQuote(projectRelative)} && ` : "";
  const read = (rel: string): string | null => {
    try {
      return fs.readFileSync(path.join(project, rel), "utf-8");
    } catch {
      return null;
    }
  };
  const sha = (text: string) => createHash("sha256").update(text).digest("hex");
  const tsconfig = read("tsconfig.json");
  if (tsconfig !== null) {
    const local = path.join(project, "node_modules/.bin/tsc");
    const useLocal = fs.existsSync(local);
    const tsc = useLocal ? "./node_modules/.bin/tsc" : "tsc";
    const solution = /"(?:references|composite)"\s*:/.test(tsconfig);
    return {
      tool: "tsc",
      probe: `${prefix}${tsc} --version`,
      command: `${prefix}${tsc} --noEmit --incremental false -p tsconfig.json`,
      configPath: [projectRelative, "tsconfig.json"].filter(Boolean).join("/"),
      ...(projectRelative ? { projectRoot: projectRelative } : {}),
      configSha256: sha(tsconfig),
      toolSha256: sha256File(useLocal ? local : resolveOnPath("tsc") ?? ""),
      ...(useLocal || resolveOnPath("tsc") ? {} : { missingTool: true }),
      ...(solution ? { skipReason: "tsconfig.json is solution-style or composite (references/composite), so a plain tsc run does not check it" } : {}),
    };
  }
  for (const rel of ["Cargo.toml"]) {
    const text = read(rel);
    if (text !== null) {
      const target = path.join(os.tmpdir(), `nexus-typecheck-${sha(project).slice(0, 16)}`);
      const manifestPath = [projectRelative, rel].filter(Boolean).join("/");
      const manifestArg = projectRelative ? ` --manifest-path ${shellPath(manifestPath)}` : "";
      return {
        tool: "cargo",
        probe: "cargo --version",
        command: `CARGO_TARGET_DIR=${shellQuote(target)} cargo check --offline --locked${manifestArg}`,
        configPath: manifestPath,
        ...(projectRelative ? { projectRoot: projectRelative } : {}),
        configSha256: sha(text),
        toolSha256: sha256File(resolveOnPath("cargo") ?? ""),
        ...(resolveOnPath("cargo") ? {} : { missingTool: true }),
      };
    }
  }
  const gomod = read("go.mod");
  if (gomod !== null) {
    const go = resolveOnPath("go");
    return {
      tool: "go",
      probe: `${prefix}go version`,
      // Offline: a module that is not already downloaded is an environment problem, never a fetch.
      command: `${prefix}GOPROXY=off GOFLAGS=-mod=mod go vet ./...`,
      configPath: [projectRelative, "go.mod"].filter(Boolean).join("/"),
      ...(projectRelative ? { projectRoot: projectRelative } : {}),
      configSha256: sha(gomod),
      toolSha256: sha256File(go ?? ""),
      ...(go ? {} : { missingTool: true }),
    };
  }
  const python = discoverPythonTypecheck(project, read, sha);
  if (!python) return null;
  return {
    ...python,
    probe: `${prefix}${python.probe}`,
    command: `${prefix}${python.command}`,
    configPath: [projectRelative, python.configPath].filter(Boolean).join("/"),
    ...(projectRelative ? { projectRoot: projectRelative } : {}),
  };
}

/** Python is checked only when the project configures pyright or mypy; the tool comes from the project's virtualenv or PATH. */
function discoverPythonTypecheck(root: string, read: (rel: string) => string | null, sha: (text: string) => string): DiscoveredTypecheck | null {
  const pyproject = read("pyproject.toml") ?? "";
  const setupCfg = read("setup.cfg") ?? "";
  const candidates: Array<{ tool: "pyright" | "mypy"; configPath: string; text: string }> = [];
  const pyrightJson = read("pyrightconfig.json");
  if (pyrightJson !== null) candidates.push({ tool: "pyright", configPath: "pyrightconfig.json", text: pyrightJson });
  if (/^\[tool\.pyright\]/m.test(pyproject)) candidates.push({ tool: "pyright", configPath: "pyproject.toml", text: pyproject });
  for (const rel of ["mypy.ini", ".mypy.ini"]) {
    const text = read(rel);
    if (text !== null) candidates.push({ tool: "mypy", configPath: rel, text });
  }
  if (/^\[tool\.mypy\]/m.test(pyproject)) candidates.push({ tool: "mypy", configPath: "pyproject.toml", text: pyproject });
  if (/^\[mypy\]/m.test(setupCfg)) candidates.push({ tool: "mypy", configPath: "setup.cfg", text: setupCfg });
  const chosen = candidates[0];
  if (!chosen) return null;
  const local = [".venv/bin", "venv/bin"].map((d) => path.join(root, d, chosen.tool)).find((f) => fs.existsSync(f));
  const resolved = local ?? resolveOnPath(chosen.tool);
  const launcher = local ? `./${path.relative(root, local)}` : chosen.tool;
  return {
    tool: chosen.tool,
    probe: `${launcher} --version`,
    command: chosen.tool === "mypy" ? `${launcher} .` : launcher,
    configPath: chosen.configPath,
    configSha256: sha(chosen.text),
    toolSha256: sha256File(resolved ?? ""),
    ...(resolved ? {} : { missingTool: true }),
  };
}

export interface TypecheckDiagnostics {
  errorCount: number;
  /** Files (as printed by the tool) that carry at least one located error. */
  files: string[];
  /** Error codes of diagnostics with no source location (configuration errors). */
  unlocatedCodes: string[];
  first: string[];

